const boardPhotos={uno:{src:"assets/hardware/arduino-uno-r3.jpg",name:"Arduino Uno Rev3",href:"https://store.arduino.cc/products/arduino-uno-rev3"},nano:{src:"assets/hardware/arduino-nano-classic.jpg",name:"Arduino Nano Classic",href:"https://store.arduino.cc/products/arduino-nano"},mega:{src:"assets/hardware/arduino-mega-2560.jpg",name:"Arduino Mega 2560 Rev3",href:"https://store.arduino.cc/products/arduino-mega-2560-rev3"},esp32:{src:"assets/hardware/esp32-devkitc-v4.png",name:"ESP32-DevKitC V4",href:"https://docs.espressif.com/projects/esp-dev-kits/en/latest/esp32/esp32-devkitc/user_guide.html"},nodemcu:{src:"assets/hardware/nodemcu-esp12e.jpg",name:"NodeMCU DevKit v1.0 · ESP-12E",href:"https://kriyaedu.com/products/nodemcu-12e-microcontroller"},pi4:{src:"assets/hardware/raspberry-pi4.jpg",name:"Raspberry Pi 4 Model B",href:"https://www.adafruit.com/product/4564"}};
function renderPhysicalBoard(){const art=byId('physical-board');art.className=`physical-board ${currentBoard}-board`;const photo=boardPhotos[currentBoard];if(!photo){art.innerHTML=physicalBoardSvg(currentBoard);return}art.innerHTML=`<a class="board-photo-link" href="${photo.href}" target="_blank" rel="noopener noreferrer" aria-label="Open the ${photo.name} hardware reference"><img class="real-board-photo" src="${photo.src}" alt="Real ${photo.name} board, shown from above" loading="lazy" referrerpolicy="no-referrer"><span class="board-photo-caption"><b>${photo.name}</b><small>Real board photo · open product reference ↗</small></span></a>`;art.querySelector('img').addEventListener('error',()=>{art.classList.add('photo-fallback');art.querySelector('img').remove();art.querySelector('.board-photo-caption small').textContent='Photo unavailable · pin layout remains model-specific'})}
function renderBoard(){const board=boards[currentBoard];renderPhysicalBoard();byId('board-label').textContent=board.title;byId('board-name').textContent=board.short;byId('board-chip').textContent=board.chip;byId('board-logic').textContent=board.logic;byId('board-caution').textContent=board.safe;byId('pinout-detail').textContent=`${board.title}: ${board.safe}`;const holder=byId('board-banks');holder.innerHTML='';board.banks.forEach((bank,idx)=>{const section=document.createElement('div');section.className='pin-bank'+(currentBoard==='pi4'?' pi-bank':'');const title=document.createElement('span');title.className='pin-bank-title';title.textContent=currentBoard==='pi4'?(idx===0?'ODD PHYSICAL PINS':'EVEN PHYSICAL PINS'):currentBoard==='uno'?['Digital Pins','Analog Pins','Power / I/O Pins'][idx]:(idx===0?'DIGITAL / HEADER PINS':'ANALOG / POWER');section.append(title);bank.forEach(id=>{const pin=board.pins.find(p=>p.id===id);if(!pin)return;const unoDigital=currentBoard==='uno'&&/^D\d+$/.test(pin.id);const unoAnalog=currentBoard==='uno'&&/^A\d+$/.test(pin.id);const displayName=unoDigital?pin.id.slice(1):unoAnalog?pin.id:pin.label.replace(' · ',' ');const detail=unoDigital||unoAnalog?[...pin.features,...(pin.notes?[pin.notes]:[])].join(' · '):`${pin.label}${pin.features.length?' · '+pin.features.join(', '):''}${pin.notes?' · '+pin.notes:''}`;const button=document.createElement('button');button.type='button';button.className=`board-pin ${pin.type}${pin.inputOnly||pin.type==='special'?' restricted':''}`;button.dataset.terminal=`B:${pin.id}`;button.title=[pin.label,pin.features.join(', '),pin.notes].filter(Boolean).join(' · ');button.setAttribute('aria-label',`${unoDigital?'Digital pin '+displayName:unoAnalog?'Analog pin '+displayName:pin.label}${detail?' · '+detail:''}`);button.innerHTML=`<span class="pin-hole"></span><span class="pin-name">${displayName}</span><span class="pin-sub">${detail}</span>`;button.addEventListener('click',()=>selectTerminal(button.dataset.terminal));section.append(button)});holder.append(section)});renderComponents();updateWires()}
function addComponent(type,x,y){const def=library.find(c=>c.type===type);if(!def)return;const id='C'+(components.length?Math.max(...components.map(c=>+c.id.slice(1)))+1:1),index=components.length;components.push({id,type,name:def.name,x:Number.isFinite(x)?x:630+(index%2)*220,y:Number.isFinite(y)?y:95+Math.floor(index/2)*145,terminals:def.terminals.map(([key,label])=>({key,label}))});renderComponents();updateWires()}
function removeComponent(id){components=components.filter(c=>c.id!==id);wires=wires.filter(w=>!w.a.startsWith(id+':')&&!w.b.startsWith(id+':'));if(selectedTerminal?.startsWith(id+':'))selectedTerminal=null;renderComponents();renderConnections();updateWires()}
function renderComponents(){const area=byId('component-bench');area.querySelectorAll('.circuit-component').forEach(e=>e.remove());byId('bench-empty').hidden=components.length>0;components.forEach(component=>{const def=library.find(x=>x.type===component.type);if(!def)return;const card=document.createElement('article');card.className='circuit-component';card.dataset.component=component.id;card.style.left=`${component.x??630}px`;card.style.top=`${component.y??95}px`;card.innerHTML=`<div class="component-head"><span class="component-title"><span class="component-glyph">${def.glyph}</span>${component.name}</span><button class="component-remove" aria-label="Remove ${component.name}">×</button></div><div class="part-visual">${componentVisual(component.type)}</div><div class="component-terminals">${component.terminals.map(t=>`<button type="button" class="terminal" data-terminal="${component.id}:${t.key}" title="Click to wire ${t.label}"><i class="terminal-dot"></i>${t.label}</button>`).join('')}</div><div class="component-state" data-state="${component.id}">${component.type==='led'?'LED off':component.type==='motor'?'Needs driver control':'Ready'}</div>`;card.querySelector('.component-remove').addEventListener('click',()=>removeComponent(component.id));card.querySelectorAll('.terminal').forEach(t=>t.addEventListener('click',()=>selectTerminal(t.dataset.terminal)));const handle=card.querySelector('.component-head');handle.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;e.preventDefault();const startX=e.clientX,startY=e.clientY,left=component.x??630,top=component.y??95;handle.setPointerCapture(e.pointerId);const move=ev=>{component.x=Math.max(8,Math.min(900,left+ev.clientX-startX));component.y=Math.max(8,Math.min(720,top+ev.clientY-startY));card.style.left=`${component.x}px`;card.style.top=`${component.y}px`;updateWires()};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end)};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end)});area.append(card)});renderConnections()}
function selectTerminal(id){if(!selectedTerminal){selectedTerminal=id;byId('connect-hint').textContent=`Selected ${terminalName(id)} — now click a second terminal`;highlightTerminals();return}if(selectedTerminal===id){selectedTerminal=null;byId('connect-hint').textContent='Choose a terminal, then choose the terminal to connect';highlightTerminals();return}const duplicate=wires.find(w=>(w.a===selectedTerminal&&w.b===id)||(w.a===id&&w.b===selectedTerminal));if(duplicate){errorModal('Those terminals are already connected.');selectedTerminal=null;highlightTerminals();return}wires.push({a:selectedTerminal,b:id});selectedTerminal=null;byId('connect-hint').textContent='Wire added. Choose another pair or start the simulation.';highlightTerminals();renderConnections();updateWires()}
function terminalName(id){if(id.startsWith('B:'))return boardByPin(id.slice(2))?.label||id.slice(2);const [componentId,key]=id.split(':');const c=components.find(x=>x.id===componentId);return `${c?.name||componentId} ${c?.terminals.find(t=>t.key===key)?.label||key}`}
function highlightTerminals(){document.querySelectorAll('[data-terminal]').forEach(el=>{el.classList.toggle('selected',el.dataset.terminal===selectedTerminal);el.classList.toggle('connected',wires.some(w=>w.a===el.dataset.terminal||w.b===el.dataset.terminal))})}
function renderConnections(){const list=byId('connection-list');list.innerHTML='';byId('wire-count').textContent=`${wires.length} connection${wires.length===1?'':'s'}`;if(!wires.length){list.innerHTML='<span class="empty-connections">No connections yet</span>';return}wires.forEach((w,i)=>{const chip=document.createElement('span');chip.className='connection-chip';chip.innerHTML=`${terminalName(w.a)} ↔ ${terminalName(w.b)} <button type="button" aria-label="Remove wire ${i+1}">×</button>`;chip.querySelector('button').addEventListener('click',()=>{wires.splice(i,1);renderConnections();updateWires()});list.append(chip)});highlightTerminals()}
function updateWires(){const svg=byId('wire-layer'),r=canvas.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${Math.max(canvas.scrollWidth,r.width)} ${Math.max(canvas.scrollHeight,r.height)}`);svg.innerHTML='';wires.forEach((w,i)=>{const a=document.querySelector(`[data-terminal="${CSS.escape(w.a)}"]`),b=document.querySelector(`[data-terminal="${CSS.escape(w.b)}"]`);if(!a||!b)return;const ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();const x1=ra.left+ra.width/2-r.left+canvas.scrollLeft,y1=ra.top+ra.height/2-r.top+canvas.scrollTop,x2=rb.left+rb.width/2-r.left+canvas.scrollLeft,y2=rb.top+rb.height/2-r.top+canvas.scrollTop;const mid=(x1+x2)/2;const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('class','wire-path');p.setAttribute('d',`M ${x1} ${y1} L ${mid} ${y1} L ${mid} ${y2} L ${x2} ${y2}`);p.style.stroke=i%2?'#f0b86c':'#68dabc';svg.append(p)});highlightTerminals()}
function setLanguageOptions(){const options=boards[currentBoard].language;const sel=byId('language-select');sel.innerHTML=options.map(x=>`<option>${x}</option>`).join('');byId('code-language-label').textContent=options[0];byId('code-model-note').textContent=currentBoard==='pi4'?'GPIO numbers in code use BCM numbering. Physical header pin numbers appear on the board.':currentBoard==='nodemcu'?'Use NodeMCU Dx names or the matching ESP8266 GPIO number.':currentBoard==='aether'?'Concept pin map only; this is not a finished microcontroller board.':'Starter code and pin identifiers match the selected board model.';byId('code-editor').value=starterFor(currentBoard,options[0]);byId('code-status').textContent='Ready to simulate'}
function starterFor(key,lang){if(lang.startsWith('MicroPython')){if(key==='nodemcu')return`from machine import Pin\nfrom time import sleep\n\nled = Pin(5, Pin.OUT)  # NodeMCU D1 = GPIO5\n\nwhile True:\n    led.value(1)\n    sleep(0.5)\n    led.value(0)\n    sleep(0.5)`;return`from machine import Pin\nfrom time import sleep\n\nled = Pin(23, Pin.OUT)\n\nwhile True:\n    led.value(1)\n    sleep(0.5)\n    led.value(0)\n    sleep(0.5)`}return boards[key].starter}
function selectBoard(key){if(simActive)stopSimulation();currentBoard=key;selectedTerminal=null;wires=[];components=[];renderBoard();setLanguageOptions();renderConnections();byId('connect-hint').textContent='Choose a terminal, then choose the terminal to connect';byId('workspace-save-status').textContent='Board changed. The previous circuit was cleared.'}
function loadDemo(){if(simActive)stopSimulation();components=[];wires=[];selectedTerminal=null;const rDef=library.find(x=>x.type==='resistor'),lDef=library.find(x=>x.type==='led');const resistor={id:'C1',type:'resistor',name:rDef.name,terminals:rDef.terminals.map(([key,label])=>({key,label}))};const led={id:'C2',type:'led',name:lDef.name,terminals:lDef.terminals.map(([key,label])=>({key,label}))};components=[resistor,led];const board=boards[currentBoard];wires=[{a:`B:${board.demo}`,b:'C1:A'},{a:'C1:B',b:'C2:A'},{a:'C2:K',b:`B:${board.ground}`}];byId('project-title').value=`${board.short} · LED blink`;byId('code-editor').value=starterFor(currentBoard,byId('language-select').value);renderComponents();updateWires();byId('workspace-save-status').textContent='LED demo loaded. Press Start simulation to check it.'}
function graph(){const g=new Map();const edge=(a,b,kind,component)=>{if(!g.has(a))g.set(a,[]);if(!g.has(b))g.set(b,[]);g.get(a).push({to:b,kind,component});g.get(b).push({to:a,kind,component})};wires.forEach(w=>edge(w.a,w.b,'wire'));components.forEach(c=>{if(['resistor','led','button','buzzer'].includes(c.type)&&c.terminals.length>=2)edge(`${c.id}:${c.terminals[0].key}`,`${c.id}:${c.terminals[1].key}`,'component',c.type)});return{g,edge}}
function pathBetween(g,start,end,allowed=()=>true){const q=[start],prev=new Map([[start,null]]);while(q.length){const n=q.shift();if(n===end)break;for(const e of g.get(n)||[]){if(prev.has(e.to)||!allowed(e))continue;prev.set(e.to,{from:n,edge:e}) ;q.push(e.to)}}if(!prev.has(end))return null;const path=[];let n=end;while(prev.get(n)){const item=prev.get(n);path.unshift(item.edge);n=item.from}return path}
function resolveCodePin(ref){let value=ref.trim().replace(/[;,)]/g,'');if(/^GPIO\d+$/i.test(value))value=value.replace(/GPIO/i,'');if(/^P\d+$/i.test(value))return boards[currentBoard].pins.find(p=>p.id===value);const direct=boards[currentBoard].pins.find(p=>p.id.toLowerCase()===value.toLowerCase()||p.label.toLowerCase()===value.toLowerCase());if(direct)return direct;if(/^\d+$/.test(value))return boards[currentBoard].pins.find(p=>p.gpio===+value&&p.type==='gpio');return null}
function codeOutputs(code,lang){const aliases=new Map();for(const match of code.matchAll(/(?:const\s+\w+\s+|#define\s+)(\w+)\s*(?:=\s*)?([A-Za-z]+\d*|\d+)\s*;?/g))aliases.set(match[1],match[2]);const resolve=raw=>aliases.get(raw)||raw;let refs=[];if(lang.includes('Python')||lang.includes('MicroPython')){for(const m of code.matchAll(/(?:LED\s*\(\s*(\d+)\s*\)|Pin\s*\(\s*(\d+)\s*,\s*Pin\.OUT|Device\s*\(\s*pin\s*=\s*(\d+))/g))refs.push(m[1]||m[2]||m[3]);if(!refs.length){for(const m of code.matchAll(/GPIO\s*\.setup\s*\(\s*(\d+)\s*,\s*GPIO\.OUT/g))refs.push(m[1])}}else{for(const m of code.matchAll(/(?:digitalWrite|analogWrite|tone|servo\.attach)\s*\(\s*([A-Za-z_]\w*|D\d+|A\d+|IO\d+|\d+)/gi))refs.push(resolve(m[1]));if(!refs.length){for(const m of code.matchAll(/pinMode\s*\(\s*([A-Za-z_]\w*|D\d+|A\d+|IO\d+|\d+)\s*,\s*OUTPUT/gi))refs.push(resolve(m[1]))}}return [...new Set(refs)]}
function validateSimulation(){const code=byId('code-editor').value,lang=byId('language-select').value;const brace=(code.match(/{/g)||[]).length-(code.match(/}/g)||[]).length;if(brace!==0)return{error:'The code has unmatched curly braces.'};const paren=(code.match(/\(/g)||[]).length-(code.match(/\)/g)||[]).length;if(paren!==0)return{error:'The code has unmatched parentheses.'};if(lang.includes('C++')&&!(/void\s+setup\s*\(/.test(code)&&/void\s+loop\s*\(/.test(code)))return{error:'Arduino-style code needs both setup() and loop() functions for this preview.'};if(lang.includes('Python')&&!(/while\s+True\s*:/.test(code)||/def\s+main\s*\(/.test(code)))return{error:'Python preview needs a while True loop or a main() function.'};const refs=codeOutputs(code,lang);if(!refs.length)return{error:'No supported output pin was found. Try digitalWrite(), LED(pin), or Pin(pin, Pin.OUT).'};const pins=refs.map(ref=>({ref,pin:resolveCodePin(ref)}));const missing=pins.find(x=>!x.pin);if(missing)return{error:`${missing.ref} is not a code pin on the selected ${boards[currentBoard].title}.`};const inputOnly=pins.find(x=>x.pin.inputOnly||!x.pin.output);if(inputOnly)return{error:`${inputOnly.pin.label} cannot be used as a GPIO output on this board.`};const {g}=graph();const gnd=boards[currentBoard].pins.find(p=>p.id===boards[currentBoard].ground);const ledComps=components.filter(c=>c.type==='led');if(!ledComps.length)return{error:'Add an LED component to run this basic output simulation.'};for(const item of pins){const bTerm=`B:${item.pin.id}`;if(!wires.some(w=>w.a===bTerm||w.b===bTerm))return{error:`${item.pin.label} is used in code but is not connected. Wire it to an output component.`};if(!gnd||!wires.some(w=>w.a===`B:${gnd.id}`||w.b===`B:${gnd.id}`))return{error:'The circuit needs a ground connection to the selected board.'};const wireOnlyShort=pathBetween(g,bTerm,`B:${gnd.id}`,e=>e.kind==='wire');if(wireOnlyShort)return{error:`${item.pin.label} is wired directly to GND. Check for a short before running.`};let validLed=false,hasResistor=false;for(const led of ledComps){const toAnode=pathBetween(g,bTerm,`${led.id}:A`),toGround=pathBetween(g,`${led.id}:K`,`B:${gnd.id}`);if(toAnode&&toGround){validLed=true;hasResistor=[...toAnode,...toGround].some(e=>e.component==='resistor');break}}if(!validLed)return{error:`No complete path from ${item.pin.label} through an LED to GND was found. Check the LED polarity and wires.`};if(!hasResistor)return{error:'Add a resistor in series with the LED before running the circuit.'};if(boards[currentBoard].voltage<=3.3&&wires.some(w=>w.a==='B:5V'||w.b==='B:5V'))return{error:'This board uses 3.3V GPIO. Do not connect its 5V rail directly to a GPIO pin.'}}return{pins:pins.map(x=>x.pin),code,lang,blink:/\b(HIGH|\.on\s*\(|\.value\s*\(\s*1)\b/i.test(code)&&/\b(LOW|\.off\s*\(|\.value\s*\(\s*0)\b/i.test(code),steadyHigh:/\b(HIGH|\.on\s*\(|\.value\s*\(\s*1)\b/i.test(code)}}
function startSimulation(){const result=validateSimulation();if(result.error){errorModal(result.error);return}stopSimulation();simActive=true;byId('run-simulation').hidden=true;byId('stop-simulation').hidden=false;byId('sim-output').classList.add('running');byId('sim-output').querySelector('b').textContent=result.blink?'LED blink preview running':(result.steadyHigh?'LED output is HIGH':'GPIO output preview running');byId('sim-output').querySelector('small').textContent=`${result.pins.map(p=>p.label).join(', ')} · ${boards[currentBoard].title}`;byId('code-status').textContent='Simulation running';const update=()=>{const on=result.blink?(Math.floor(Date.now()/500)%2===0):result.steadyHigh;components.forEach(c=>{const card=document.querySelector(`[data-component="${c.id}"]`);if(!card)return;const state=card.querySelector('.component-state');if(c.type==='led'){card.classList.toggle('sim-on',on);state.textContent=on?'LED lit':'LED off'}else if(c.type==='buzzer')state.textContent=on?'Output active':'Output idle'})};update();if(result.blink)simTimer=setInterval(update,250)}
function stopSimulation(){if(simTimer){clearInterval(simTimer);simTimer=null}simActive=false;byId('run-simulation').hidden=false;byId('stop-simulation').hidden=true;byId('sim-output').classList.remove('running');byId('sim-output').querySelector('b').textContent='Simulation stopped';byId('sim-output').querySelector('small').textContent='Build a circuit and run a supported starter sketch.';byId('code-status').textContent='Ready to simulate';components.forEach(c=>{const card=document.querySelector(`[data-component="${c.id}"]`);if(card){card.classList.remove('sim-on');const s=card.querySelector('.component-state');if(s)s.textContent=c.type==='led'?'LED off':'Ready'}})}
function errorModal(message){byId('error-message').textContent=message;const m=byId('error-modal');m.classList.add('open');m.setAttribute('aria-hidden','false');byId('error-close').focus()}
function closeError(){const m=byId('error-modal');m.classList.remove('open');m.setAttribute('aria-hidden','true')}
function setBoard(key){if(simActive)stopSimulation();currentBoard=key;components=[];wires=[];selectedTerminal=null;renderBoard();setLanguageOptions();renderConnections();byId('connect-hint').textContent='Choose a terminal, then choose the terminal to connect'}
renderLibrary();renderBoard();setLanguageOptions();
byId('board-select').addEventListener('change',e=>setBoard(e.target.value));byId('component-search').addEventListener('input',e=>renderLibrary(e.target.value));byId('load-demo').addEventListener('click',()=>loadDemo());byId('clear-workspace').addEventListener('click',()=>{stopSimulation();components=[];wires=[];selectedTerminal=null;byId('project-title').value='Untitled circuit';renderComponents();updateWires();byId('connect-hint').textContent='Choose a terminal, then choose the terminal to connect'});byId('language-select').addEventListener('change',e=>{byId('code-language-label').textContent=e.target.value;byId('code-editor').value=starterFor(currentBoard,e.target.value)});byId('reset-code').addEventListener('click',()=>{byId('code-editor').value=starterFor(currentBoard,byId('language-select').value);byId('code-status').textContent='Starter restored'});byId('run-simulation').addEventListener('click',startSimulation);byId('stop-simulation').addEventListener('click',stopSimulation);byId('error-close').addEventListener('click',closeError);byId('error-modal').querySelector('.error-backdrop').addEventListener('click',closeError);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeError()});window.addEventListener('resize',updateWires);byId('circuit-canvas').addEventListener('scroll',updateWires);
